'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import axios from 'axios';
import { travelDetailsSchema, type TravelDetailsFormData } from '@/app/lib/validations/application';
import { API_BASE_URL } from '@/app/lib/constants/api';
import Input from '@/app/components/ui/Input';
import Select from '@/app/components/ui/Select';
import Button from '@/app/components/ui/Button';
import Checkbox from '@/app/components/ui/Checkbox';
import { LoadingSpinner } from '@/app/components/ui/Loader';

export default function TravelDetailsPage({ params }: { params: { id: string } }) {
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [isTransiting, setIsTransiting] = useState(false);

  const {
    register,
    handleSubmit,
    setValue,
    watch,
    formState: { errors },
  } = useForm<TravelDetailsFormData>({
    resolver: zodResolver(travelDetailsSchema),
  });

  const watchIsTransiting = watch('isTransiting');

  useEffect(() => {
    setIsTransiting(watchIsTransiting);
  }, [watchIsTransiting]);

  useEffect(() => {
    fetchApplicationData();
  }, [params.id]);

  const fetchApplicationData = async () => {
    try {
      const token = localStorage.getItem('access_token');
      const { data } = await axios.get(`${API_BASE_URL}/applications/${params.id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (data.pointOfEntry) {
        setValue('isTransiting', data.isTransiting || false);
        setValue('transitDestination', data.transitDestination || '');
        setValue('pointOfEntry', data.pointOfEntry);
        setValue('arrivalDate', data.arrivalDate ? data.arrivalDate.split('T')[0] : '');
        setValue('flightVesselNumber', data.flightVesselNumber);
        setValue('purposeOfVisit', data.purposeOfVisit);
        setIsTransiting(data.isTransiting || false);
      }
    } catch (error) {
      console.error('Failed to fetch application:', error);
    } finally {
      setLoading(false);
    }
  };

  const onSubmit = async (data: TravelDetailsFormData) => {
    setSubmitting(true);
    try {
      const token = localStorage.getItem('access_token');
      await axios.put(
        `${API_BASE_URL}/applications/${params.id}/travel-details`,
        data,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      router.push(`/application/${params.id}/personal-info`);
    } catch (error: any) {
      console.error('Submission error:', error);
      alert(error.response?.data?.message || 'Failed to save. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <LoadingSpinner />
      </div>
    );
  }

  return (
    <div>
      <div className="mb-8">
        <h1 className="text-2xl md:text-3xl font-bold text-gray-900 mb-2">
          Travel Details
        </h1>
        <p className="text-gray-600">
          Provide information about your upcoming trip to the United States.
        </p>
      </div>

      <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
        <div className="bg-white rounded-lg border border-gray-200 p-6 space-y-6">
          <div>
            <Checkbox
              label="I am transiting through the U.S. to another country"
              {...register('isTransiting')}
            />
          </div>

          {isTransiting && (
            <Input
              label="Transit Destination"
              placeholder="Final destination country"
              error={errors.transitDestination?.message}
              required
              {...register('transitDestination')}
            />
          )}

          <Input
            label="Point of Entry"
            placeholder="City or airport code (e.g., JFK, LAX)"
            error={errors.pointOfEntry?.message}
            helperText="Where will you first enter the United States?"
            required
            {...register('pointOfEntry')}
          />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Input
              label="Arrival Date"
              type="date"
              error={errors.arrivalDate?.message}
              required
              {...register('arrivalDate')}
            />

            <Input
              label="Flight/Vessel Number"
              placeholder="AA1234"
              error={errors.flightVesselNumber?.message}
              required
              {...register('flightVesselNumber')}
            />
          </div>

          <Select
            label="Purpose of Visit"
            error={errors.purposeOfVisit?.message}
            required
            {...register('purposeOfVisit')}
          >
            <option value="">Select purpose</option>
            <option value="TOURISM">Tourism</option>
            <option value="BUSINESS">Business</option>
            <option value="TRANSIT">Transit</option>
          </Select>
        </div>

        <div className="flex justify-between">
          <Button
            type="button"
            variant="outline"
            onClick={() => router.back()}
          >
            Back
          </Button>
          <Button
            type="submit"
            disabled={submitting}
            className="min-w-[200px]"
          >
            {submitting ? 'Saving...' : 'Continue'}
          </Button>
        </div>
      </form>
    </div>
  );
}
